mapper.insert:
INSERT INTO reservation (user_id, seat_id, slot_start, slot_end, status, check_in_deadline, version)
SELECT #{userId}, #{seatId}, start_time, end_time, 'RESERVED', #{deadline}, 0
FROM slot WHERE start_time = #{slotStart}

mapper.select:
SELECT  FROM reservation WHERE user_id = #{userId}
AND status = #{status}
ORDER BY slot_start DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT  FROM reservation
WHERE status = 'RESERVED' AND check_in_deadline < #{now}
ORDER BY check_in_deadline, id LIMIT #{limit}

SELECT  FROM reservation
WHERE status = 'CHECKED_IN' AND slot_end < #{now}
ORDER BY slot_end, id LIMIT #{limit}

SELECT r.id, r.user_id, r.seat_id, r.slot_start, r.slot_end, r.status,
       r.check_in_deadline, r.checked_in_at, r.version,
       u.student_no, u.name AS student_name, s.room, s.floor, s.seat_no
FROM reservation r
JOIN app_user u ON u.id = r.user_id
JOIN seat s ON s.id = r.seat_id

    u.student_no = #{studentNo}
    AND r.seat_id = #{seatId}
    AND r.status = #{status}
    AND r.slot_start >= #{from}
    AND r.slot_start < #{to}

ORDER BY r.slot_start DESC, r.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) AS total,
       COALESCE(SUM(status IN ('CHECKED_IN', 'COMPLETED')), 0) AS checked_in,
       COALESCE(SUM(status = 'EXPIRED'), 0) AS no_show
FROM reservation

    slot_start >= #{from}
    AND slot_start < #{to}
